CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', approval_status text NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_approved(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND approval_status='approved') $$;
CREATE POLICY "own role read" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY "own or admin profiles" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin'));
INSERT INTO public.profiles(id,name,email,approval_status,created_at) SELECT id,coalesce(raw_user_meta_data->>'name',''),coalesce(email,''),'approved',created_at FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE FUNCTION public.create_pending_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,email) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'name',''),120),coalesce(NEW.email,'')); RETURN NEW; END $$;
CREATE TRIGGER create_pending_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_pending_profile();
CREATE TABLE public.access_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, kind text NOT NULL, page text NOT NULL DEFAULT '', detail jsonb NOT NULL DEFAULT '{}'::jsonb, user_agent text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.access_events TO authenticated; GRANT ALL ON public.access_events TO service_role;
ALTER TABLE public.access_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin audit read" ON public.access_events FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE INDEX access_events_user_time ON public.access_events(user_id,created_at DESC);
CREATE FUNCTION public.record_access(_kind text,_page text DEFAULT '',_detail jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF _kind NOT IN ('login','page','search','logout') THEN RAISE EXCEPTION 'Invalid event'; END IF; IF octet_length(_detail::text)>4000 THEN RAISE EXCEPTION 'Event too large'; END IF; h:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb; INSERT INTO public.access_events(user_id,kind,page,detail,user_agent) VALUES(auth.uid(),_kind,left(_page,200),_detail,left(coalesce(h->>'user-agent',''),500)); END $$;
REVOKE ALL ON FUNCTION public.record_access(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_access(text,text,jsonb) TO authenticated;
CREATE FUNCTION public.audit_account_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; u uuid; BEGIN r:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; u:=(r->>'user_id')::uuid; IF auth.uid() IS NOT NULL AND u IS NOT NULL THEN INSERT INTO public.access_events(user_id,kind,page,detail,user_agent) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,jsonb_build_object('id',r->>'id','name',coalesce(r->>'name',r->>'title'),'status',r->>'status'),left(coalesce((coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb)->>'user-agent',''),500)); END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['leads','proposals','site_prompts','scripts','daily_leads','user_settings','push_subscriptions','notifications','wa_scheduled','lead_blocks','block_items','campaigns','pl_lists','pl_contacts','pl_scripts','pl_campaigns','pl_queue','mining_feedback','jarvis_tokens'] LOOP EXECUTE format('CREATE POLICY "approved accounts only" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_approved(auth.uid())) WITH CHECK (public.is_approved(auth.uid()))',t); IF t NOT IN ('jarvis_tokens','push_subscriptions','user_settings') THEN EXECUTE format('CREATE TRIGGER account_activity_audit AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_account_changes()',t); END IF; END LOOP; END $$;